// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // WIDE admissible domain: any caller, any funding amount. Only exclude the
        // deployer itself (which happens to be the owner) and the contract address,
        // since "non-owner may not drain" is only meaningful for genuine third parties.
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // Fund the contract with the fuzzed amount so a draining bug has funds to take.
        vm.deal(address(c), amount);

        uint256 callerStart = actor.balance;
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a non-owner call to withdrawAll must revert, the caller must
        // not be paid, and the contract must keep every wei it held.
        assertTrue(!ok && actor.balance == callerStart && address(c).balance == amount);
    }
}

